CREATE TABLE IF NOT EXISTS sources (id BIGINT AUTO_INCREMENT PRIMARY KEY, source_key VARCHAR(255) UNIQUE NOT NULL, institution TEXT, homepage TEXT, record_url TEXT, api_url TEXT, rights TEXT, image_policy TEXT, retrieved_at DATETIME, content_sha256 CHAR(64), notes TEXT);
CREATE TABLE IF NOT EXISTS periods (id BIGINT AUTO_INCREMENT PRIMARY KEY, period_key VARCHAR(255) UNIQUE NOT NULL, name VARCHAR(255) NOT NULL, parent_id BIGINT NULL, start_year INT, end_year INT, notes TEXT, FOREIGN KEY(parent_id) REFERENCES periods(id));
CREATE TABLE IF NOT EXISTS objects (id BIGINT AUTO_INCREMENT PRIMARY KEY, external_id VARCHAR(255) UNIQUE, title TEXT NOT NULL, period_id BIGINT, object_type VARCHAR(255), culture VARCHAR(255), script VARCHAR(255), date_from INT, date_to INT, site TEXT, material TEXT, description TEXT, source_id BIGINT, image_url TEXT, rights TEXT, provenance TEXT, created_at DATETIME DEFAULT CURRENT_TIMESTAMP, updated_at DATETIME DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(period_id) REFERENCES periods(id), FOREIGN KEY(source_id) REFERENCES sources(id));
CREATE TABLE IF NOT EXISTS readings (id BIGINT AUTO_INCREMENT PRIMARY KEY, object_id BIGINT NOT NULL, reading_type VARCHAR(64) NOT NULL, transliteration TEXT, arabic_interpretation TEXT, english_interpretation TEXT, reviewer VARCHAR(255), confidence DOUBLE, status VARCHAR(64) DEFAULT 'candidate', created_at DATETIME DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(object_id) REFERENCES objects(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS translation_results (id BIGINT AUTO_INCREMENT PRIMARY KEY, object_id BIGINT NULL, source_language VARCHAR(64) NOT NULL, target_language VARCHAR(64) NOT NULL, source_text TEXT NOT NULL, mode VARCHAR(32) NOT NULL, output LONGTEXT, confidence DOUBLE, alternatives_json JSON, proof_notes_json JSON, provenance_json JSON, review_required BOOLEAN DEFAULT TRUE, created_at DATETIME DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(object_id) REFERENCES objects(id) ON DELETE SET NULL);
CREATE TABLE IF NOT EXISTS chatbot_sessions (id VARCHAR(128) PRIMARY KEY, provider VARCHAR(128) NOT NULL, model VARCHAR(255), evidence_json JSON, created_at DATETIME DEFAULT CURRENT_TIMESTAMP, updated_at DATETIME DEFAULT CURRENT_TIMESTAMP);
